async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  answerFrame(ws, session, validation, undefined);
}

// Answered off the per-session lock, beside ping: a history request is not a turn and mutates nothing.
async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  validation: ValidationResult,
  sessionStore: SessionStore | undefined
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_sessions') await handleListSessions(ws, session, message, sessionStore);
}

// The user id is read from the connection, never from the frame, so a client-named one cannot widen the answer.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore: SessionStore | undefined
): Promise<void> {
  try {
    const summaries = await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before});
    sendJson(ws, {type: 'session_list', sessions: (summaries ?? []).map(toSummaryFrame)});
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listing conversations failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
    // The frame carries no store detail: what a client shows for a failed history is a failure, not an empty list.
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

const toSummaryFrame = ({sessionId, createdAt, updatedAt, entryCount}: SessionSummary): SessionSummaryFrame => ({
  sessionId,
  createdAt: createdAt.toISOString(),
  updatedAt: updatedAt.toISOString(),
  entryCount,
});

