#!/usr/bin/env node
// One-off: repoint [validated by: TITLE](path#Lnn) anchors in branch-authored specs
// (which repoint-spec-anchors.mjs skips for lack of a baseline) by locating TITLE's
// it( declaration in the cited file. Prints anything it cannot resolve uniquely.
import {readFileSync, writeFileSync} from 'node:fs';

const specs = process.argv.slice(2);
const anchor = /\(\[validated by: ([^\]]+)\]\(\.\.\/\.\.\/(src\/[^\s)]+\.test\.ts)#L(\d+)\)\)/g;

for (const specPath of specs) {
  const spec = readFileSync(specPath, 'utf8');
  const fixes = [];
  for (const [, title, file, line] of spec.matchAll(anchor)) {
    const source = readFileSync(file, 'utf8').split('\n');
    const matches = [];
    for (const [index, text] of source.entries()) {
      const trimmed = text.trim();
      if ((trimmed.startsWith("it('") || trimmed.startsWith('it("')) && trimmed.slice(4).startsWith(title)) {
        matches.push(index + 1);
      }
    }
    if (matches.length !== 1) {
      console.log(`${specPath}: ${file} "${title}" -> ${matches.length} matches (${matches.join(',')})`);
      continue;
    }
    if (matches[0] !== Number(line)) fixes.push({from: `(${file}#L${line})`, to: `(${file}#L${matches[0]})`});
  }
  let updated = spec;
  for (const {from, to} of fixes) updated = updated.replaceAll(from, to);
  if (updated !== spec) {
    writeFileSync(specPath, updated);
    console.log(`${specPath}: ${fixes.length} anchor(s) repointed`);
  } else {
    console.log(`${specPath}: all anchors already current`);
  }
}

